// Parse DeepSeek response and prepare route data
const raw = $input.first().json;
const content = raw.choices?.[0]?.message?.content || "";

const cleaned = content.replace(/```json/g, "").replace(/```/g, "").trim();

let data;
try {
  data = JSON.parse(cleaned);
} catch (e) {
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (match) {
    data = JSON.parse(match[0]);
  } else {
    throw new Error("Failed to parse AI response: " + cleaned.substring(0, 200));
  }
}

// Get source info from webhook body
const body = $items("Webhook")[0]?.json?.body || {};

return [{
  json: {
    route_title: data.route_title || "",
    city: data.city || "",
    country: data.country || "",
    destination: data.destination || data.country || "",
    route_theme: data.route_theme || "",
    mood: data.mood || "",
    places: JSON.stringify(data.days || []),
    summary: data.summary || "",
    raw_json: data,
    source_url: body.source_url || "xiaohongshu",
    status: "published",
    quality_score: 80,
    target_user: data.travel_type || "",
    best_time: data.best_time || "",
    days_count: data.days_count || data.days?.length || null,
    budget_level: data.budget_level || "",
    travel_type: data.travel_type || "",
    pace: data.pace || "",
    tags: data.tags ? "小红书精选," + data.tags : "小红书精选",
    cover_url: "",
    likes: 0
  }
}];

// Split days from raw_json
const routeId = $input.first().json.id;
const raw = $input.first().json.raw_json || {};
const days = raw.days || [];

if (!routeId) {
  throw new Error("No route_id returned from Postgres insert");
}
if (days.length === 0) {
  throw new Error("No days found in raw_json");
}

return days.map((day, index) => ({
  json: {
    route_id: routeId,
    day_number: day.day || index + 1,
    title: day.title || "Day " + (index + 1),
    summary: day.summary || "",
    places: day.places || []
  }
}));

// Split places per day
const dayId = $input.first().json.id;
const dayNumber = $input.first().json.day_number;

const splitDaysItems = $items("Split Days");
const matched = splitDaysItems.find(
  item => String(item.json.day_number) === String(dayNumber)
);
const places = matched?.json?.places || [];

if (places.length === 0) return [];

return places.map((place, index) => ({
  json: {
    day_id: dayId,
    place_name: place.name || place.place_name || "",
    visit_time: place.time || place.visit_time || "",
    duration_min: place.duration_min || null,
    description: place.description || "",
    intro: place.intro || "",
    category: place.category || "景点",
    rating: place.rating || null,
    price: place.price || "",
    tags: Array.isArray(place.tags) ? place.tags.join(",") : (place.tags || ""),
    place_order: index + 1,
    latitude: place.lat || null,
    longitude: place.lng || null,
    image_url: "",
    address: place.address || ""
  }
}));

// Collect all route info to return via webhook response
const routeItems = $items("Postgres Routes");
const route = routeItems[0]?.json || {};

return [{
  json: {
    success: true,
    route_id: route.id,
    route_title: route.route_title,
    city: route.city,
    country: route.country,
    days_count: route.days_count
  }
}];
